export type IconName = keyof typeof icons;

type Props = SVGProps<SVGSVGElement> & {
  name: IconName;
  size?: number;
};

export default function Icon({ name, size = 20, ...props }: Props) {
  const { viewBox, content } = icons[name];

  return (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      fill="currentColor"
      aria-hidden="true"
      {...props}
    >
      {content}
    </svg>
  );
}
